## ------------------------------------------------------------------------
## 2. Run simulate.r as a subprocess: real end-to-end smoke test, script
##    left completely unmodified.
## ------------------------------------------------------------------------
run_simulate <- function(seed_idx = "1", scenario_idx = "1") {
  old_wd <- getwd()
  on.exit(setwd(old_wd), add = TRUE)
  setwd(file.path(tmp_root, "code"))
  out <- suppressWarnings(system2(
    RSCRIPT_BIN,
    args = c("simulate.r", "../raw/input.csv", "../raw/seed.csv", seed_idx,
             "../raw/scenario.csv", scenario_idx),
    stdout = TRUE, stderr = TRUE
  ))
  status <- attr(out, "status")
  list(status = if (is.null(status)) 0L else status, output = out)
}

