## Run everything through testthat's summary reporter (see test-func.R for
## why with_reporter() is used: it lets a failing test report without
## aborting the rest of the suite).
## ==========================================================================
invisible(with_reporter("summary", start_end_reporter = TRUE, {

test_that("simulate.r runs end-to-end on tiny fixtures (incl. a multi-transposon scenario row) and writes a well-formed .rda", {
  res <- run_simulate(seed_idx = "1", scenario_idx = "1")
  if (!identical(res$status, 0L)) {
    cat("\n---- simulate.r stdout/stderr (see below for where it failed) ----\n")
    cat(paste(res$output, collapse = "\n"), "\n")
    cat("-------------------------------------------------------------------\n")
    cat("NOTE: if this failure mentions func_analysis.r or a column named\n",
        "transposonEffect/homologousAutoRecom, see this file's header comment\n",
        "-- both are assumption-based fixtures this suite had to infer.\n", sep = "")
  }
  expect_equal(res$status, 0L)

  rda_path <- file.path(tmp_root, "data", "tPn--1_1.rda")
  expect_true(file.exists(rda_path))

  if (file.exists(rda_path)) {
    e <- new.env()
    load(rda_path, envir = e)
    expect_true(all(c("rec.host", "rec.transposon", "rec.offspring") %in% ls(e)))
    ## 2 generations requested -> rows 0..2 recorded -> 3 rows; 6 individuals -> 6 columns
    expect_equal(dim(e$rec.host), c(3, 6))
    expect_equal(dim(e$rec.transposon), c(3, 6))
    expect_equal(dim(e$rec.offspring), c(3, 6))
    ## every host should carry a ";"-joined pair of haplotype genome strings
    expect_true(all(grepl(";", as.matrix(e$rec.host)[1, ])))
  }
})

